function [q, loss] = quest(bv, rv, w, n)
%QUEST  The q-method on n <= 16 weighted pairs: Davenport's K, its largest eigenvalue by Jacobi; the
%   loss is the weight sum less that eigenvalue.
%   bv: real[1][3][16] (passed a plain number)
%   rv: real[1][3][16] (passed a plain number)
%   w: real[1][16] (passed a plain number)
%   n: int (passed a whole number)
%   returns q: real[1][4] (passed a plain number)
%   returns loss: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    q = zeros(4, 1);
    loss = 0;
    bb = zeros(3, 3);
    ws = 0;
    for l = (0):((n) - 1)
        wl = w((l) + 1);
        ws = (ws + wl);
        i = ((0):((3) - 1)).';
        j = (0):((3) - 1);
        bb((i) + 1, (j) + 1) = (bb((i) + 1, (j) + 1) + ((wl .* (bv((l) + 1, (i) + 1)).') .* rv((l) + 1, (j) + 1)));
    end
    sg = ((bb(1, 1) + bb(2, 2)) + bb(3, 3));
    z = [(bb(2, 3) - bb(3, 2)); (bb(3, 1) - bb(1, 3)); (bb(1, 2) - bb(2, 1))];
    k = zeros(4, 4);
    for i = (0):((3) - 1)
        j = ((0):((3) - 1)).';
        k((i) + 1, (j) + 1) = ((((bb((i) + 1, (j) + 1)).' + bb((j) + 1, (i) + 1)) - asils.pc.vchoose((i == j), sg, 0))).';
        k((i) + 1, 4) = z((i) + 1);
        k(4, (i) + 1) = z((i) + 1);
    end
    k(4, 4) = sg;
    [lam, v] = asils.relations.nav.jacobi_eig4(k);
    im = 0;
    for i = (1):((4) - 1)
        if (lam((i) + 1) > lam((im) + 1))
            im = i;
        end
    end
    q = asils.relations.shared.qnorm([v(1, (im) + 1); v(2, (im) + 1); v(3, (im) + 1); v(4, (im) + 1)]);
    loss = (ws - lam((im) + 1));
end
